pattern:
echo "=== (c) hang-retry ===" curl -sS --max-time 40 -N -X POST $B -H 'content-type: application/json' --data-binary '{"model":"hang","stream":true,"max_tokens":8,"messages":[{"role":"user","content":"hi"}]}' -o /tmp/opencode/shimtest/c.txt -w "http=%{http_code} t=%{time_total}
" grep -o '^event: [a-z_]*' /tmp/opencode/shimtest/c.txt sort uniq -c echo "LIVE/DELTA:" grep -o 'LIVE_\|DELTA\|FALLBACK_TEXT' /tmp/opencode/shimtest/c.txt tr '
' ' ' echo echo "=== (a) live stream ===" curl -sS --max-time 30 -N -X POST $B -H 'content-type: application/json' --data-binary '{"model":"ok","stream":true,"max_tokens":8,"messages":[{"role":"user","content":"hi"}]}' -o /tmp/opencode/shimtest/a2.txt -w "http=%{http_code} t=%{time_total}
" grep -o '^event: [a-z_]*' /tmp/opencode/shimtest/a2.txt sort uniq -c echo "=== (d) fallback ===" curl -sS --max-time 30 -N -X POST $B -H 'content-type: application/json' --data-binary '{"model":"regress","stream":true,"max_tokens":8,"messages":[{"role":"user","content":"hi"}]}' -o /tmp/opencode/shimtest/d2.txt -w "http=%{http_code} t=%{time_total}
" grep -c FALLBACK_TEXT /tmp/opencode/shimtest/d2.txt echo "--- shim3b journal ---" cat /tmp/opencode/shimtest/shim3b.log
